    bb=np.array([s["correct"] for r in b for s in r["samples"]],dtype=float)
    dd=bb-aa
    print("Original",gensummary(a),"Edited",gensummary(b),"Delta",round(dd.mean(),4),"SE",round(dd.std(ddof=1)/np.sqrt(len(dd)),4))
